df_2024["source_document"] = "Laporan Tahunan 2024 Mahkamah Agung Republik Indonesia"
df_2024["verification_status"] = "VERIFIED"
df_2024["data_quality_flag"] = "NORMAL"

# Export individual CSV and update master Excel workbook
csv_2024_path = os.path.join(proc_dir, "master_judiciary_open_data_2024.csv")
df_2024.to_csv(csv_2024_path, index=False, encoding="utf-8")
df_2024.to_csv(os.path.join(pkg_dir, "data/master_judiciary_open_data_2024.csv"), index=False, encoding="utf-8")

# Update Excel Workbook
wb_path = os.path.join(proc_dir, "JPAIS_Master_Judicial_Open_Data_2024_2025.xlsx")
with pd.ExcelWriter(wb_path, engine="openpyxl") as writer:
    df_2024.to_excel(writer, sheet_name="OpenData_2024", index=False)
    if os.path.exists(os.path.join(proc_dir, "master_20_indicators_2025.csv")):
        pd.read_csv(os.path.join(proc_dir, "master_20_indicators_2025.csv")).to_excel(writer, sheet_name="Master_2025", index=False)
    if os.path.exists(os.path.join(proc_dir, "longitudinal_ma_caseload_2021_2025.csv")):
        pd.read_csv(os.path.join(proc_dir, "longitudinal_ma_caseload_2021_2025.csv")).to_excel(writer, sheet_name="Longitudinal_MA", index=False)

# Update dataset-metadata.json
kaggle_meta = {
    "title": "Indonesia Judicial Transparency & Caseload (2021-2025)",
    "id": "judicialcollege/indonesian-court-transparency-scorecard",
    "licenses": [{"name": "CC-BY-4.0"}]
}
with open(os.path.join(pkg_dir, "dataset-metadata.json"), "w", encoding="utf-8") as f:
    json.dump(kaggle_meta, f, indent=2)

print(f"--> FY 2024 Dataset exported to: {csv_2024_path}")
print(f"--> Master Multi-Year Excel generated at: {wb_path}")
